update.foreach:
UPDATE user
userName = #{item.userName}, account = #{item.account}, balance = #{item.balance}, wechatOpenid = #{item.wechatOpenid}, email = #{item.email}, phone = #{item.phone}, `describe` = #{item.describe}, level = #{item.level}, avatarPath = #{item.avatarPath}, uploadTime = #{item.uploadTime}, vipCreateTime = #{item.vipCreateTime}, createTime = #{item.createTime}, `delete` = #{item.delete}, uploadBackground = #{item.uploadBackground}, uploadGoods = #{item.uploadGoods}, updateAvatar = #{item.updateAvatar},
WHERE id = #{item.id}
